-- Day planner details for Bangkok hangout places: Wikidata id, short descriptions and a photo (with its author and
-- licence) from Wikidata / Wikimedia Commons (CC0 data; photos under their own free licences, credited in the app),
-- opening hours from OpenStreetMap (ODbL), and a prominence score (0–30: Wikidata / Wikipedia / photo / website /
-- hours / heritage / English name, +8 for ~50 of Bangkok's best-known sights) used to pick day-plan stops.
-- 2094 places.

update public.places p
set wikidata = v.wikidata,
    description_en = v.description_en,
    description_th = v.description_th,
    image_url = v.image_url,
    image_credit = v.image_credit,
    image_page = v.image_page,
    opening_hours = v.opening_hours,
    prominence = v.prominence
